    $seoDesc  = 'Liste complète des athlètes français d\'athlétisme avec records, clubs et statistiques.';
} elseif ($page === 'noms') {
    $nomQseo = trim($_GET['q'] ?? '');
    if ($nomQseo !== '') {
        $nomQseo = strtoupper($nomQseo);
        $seoTitle = htmlspecialchars($nomQseo) . ' — Tous les athlètes portant ce nom | Bokonzi';
