<script>
const BASE_API = <?= json_encode($BASE_API_JS) ?>;
<?php if (BK_IS_LOCAL): ?>
// MODE LOCAL : auto-injection de bk_key (URL param uniquement, pas de header pour eviter CORS preflight)
