            html += '<div style="font-size:40px;margin-bottom:8px;">&#127939;</div>';
            html += '<button onclick="_clubSprintLoad(\'' + s + '\')" style="padding:8px 20px;background:linear-gradient(135deg,#ff6b6b,#ee5a24);border:none;border-radius:8px;color:#fff;font-size:14px;font-weight:700;cursor:pointer;">Charger la composition sprint</button>';
            html += '</div>';
        } else {
            var sd = sprintData;
            var sexeF = sprintSexe;

            // --- 4x100m ---
            if (sd.relay_4x100) {
                ['M', 'F'].forEach(function(sx) {
                    if (sexeF && sexeF !== sx) return;
                    var relay = sd.relay_4x100[sx];
                    if (!relay || !relay.equipe || !relay.equipe.length) return;
                    html += '<div style="background:linear-gradient(135deg,#161b22,#1c2333);border:1px solid #30363d;border-radius:12px;padding:16px;margin-bottom:16px;">';
                    html += '<div style="font-size:16px;font-weight:700;color:#e6edf3;margin-bottom:12px;">';
                    html += '<span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:11px;font-weight:700;' + (sx === 'M' ? 'background:#3b82f620;color:#60a5fa;border:1px solid #3b82f640;' : 'background:#ec489920;color:#f472b6;border:1px solid #ec489940;') + '">' + (sx === 'M' ? 'HOMMES' : 'FEMMES') + '</span>';
                    html += ' 4x100m';
                    if (relay.temps_estime_brut) html += ' &mdash; <span style="color:#ff6b6b;font-weight:800;">' + relay.temps_estime_brut + '</span>';
                    html += '</div>';

                    // Piste visuelle
                    html += '<div style="display:flex;gap:0;">';
                    var laneBgs = ['#1a1e2e', '#1e2a2e', '#2a1e1e', '#1e1e2a'];
                    relay.equipe.forEach(function(p, i) {
                        html += '<div style="flex:1;padding:12px 8px;text-align:center;border:1px solid #30363d;background:' + (laneBgs[i] || '#1a1e2e') + ';' + (i === 0 ? 'border-radius:10px 0 0 10px;' : '') + (i === relay.equipe.length - 1 ? 'border-radius:0 10px 10px 0;' : '') + '">';
                        html += '<div style="font-size:10px;color:#8b949e;font-weight:700;">RELAYEUR ' + p.poste + '</div>';
                        html += '<div style="font-size:10px;color:#6c5ce7;margin-bottom:6px;">' + p.role + '</div>';
                        html += '<div style="font-size:13px;font-weight:700;color:#e6edf3;"><a href="?page=profil&id=' + p.athlete.id_externe + '" style="color:#58a6ff;text-decoration:none;">' + _compE(p.athlete.nom) + '</a></div>';
                        html += '<div style="font-size:12px;color:#f59e0b;margin-top:4px;">' + (p.athlete.perf_brut || _compP(p.athlete.perf_int)) + '</div>';
                        html += '</div>';
                    });
                    html += '</div>';

                    if (relay.temps_estime_brut) {
                        html += '<div style="text-align:center;margin-top:10px;padding:10px;background:#ff6b6b15;border:1px solid #ff6b6b40;border-radius:8px;">';
                        html += '<div style="color:#8b949e;font-size:11px;">Temps estime (somme 100m - 2.50s passages)</div>';
                        html += '<div style="font-size:24px;font-weight:800;color:#ff6b6b;">' + relay.temps_estime_brut + '</div>';
                        html += '</div>';
                    }

                    if (relay.remplacants && relay.remplacants.length) {
                        html += '<div style="margin-top:8px;color:#8b949e;font-size:12px;">Remplacants : ';
                        relay.remplacants.forEach(function(r, i) {
                            if (i) html += ', ';
                            html += '<a href="?page=profil&id=' + r.id_externe + '" style="color:#58a6ff;text-decoration:none;font-weight:600;">' + _compE(r.nom) + '</a> (' + (r.perf_brut || _compP(r.perf_int)) + ')';
                        });
                        html += '</div>';
                    }
                    html += '</div>';
                });
            }

            // --- Estimation 4x100m par annee ---
            if (sd.estimation_par_annee && sd.estimation_par_annee.length) {
                var estByS = {};
                sd.estimation_par_annee.forEach(function(e) {
                    if (!estByS[e.sexe]) estByS[e.sexe] = [];
                    estByS[e.sexe].push(e);
                });
                ['M', 'F'].forEach(function(sx) {
                    if (sexeF && sexeF !== sx) return;
                    var ests = estByS[sx];
                    if (!ests || !ests.length) return;
                    html += '<div style="background:#161b22;border:1px solid #30363d;border-radius:12px;padding:16px;margin-bottom:16px;">';
                    html += '<div style="font-size:15px;font-weight:700;color:#e6edf3;margin-bottom:12px;">';
                    html += '<span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:11px;font-weight:700;' + (sx === 'M' ? 'background:#3b82f620;color:#60a5fa;border:1px solid #3b82f640;' : 'background:#ec489920;color:#f472b6;border:1px solid #ec489940;') + '">' + (sx === 'M' ? 'H' : 'F') + '</span>';
                    html += ' Estimation 4x100m par annee</div>';

                    // Trouver la meilleure annee
                    var bestEst = null;
                    ests.forEach(function(e) { if (e.temps_estime_int > 0 && (!bestEst || e.temps_estime_int < bestEst.temps_estime_int)) bestEst = e; });

                    var thRow = '<tr><th>Annee</th><th>4x100m</th><th>Relayeur 1</th><th>Relayeur 2</th><th>Relayeur 3</th><th>Relayeur 4</th></tr>';
                    html += '<div class="table-wrap">';
                    html += '<table class="bk-table">' + thRow + '</table>';
                    html += '<table class="bk-table">';
                    ests.forEach(function(e) {
                        var isBest = bestEst && e.annee === bestEst.annee && e.temps_estime_int > 0;
                        html += '<tr' + (isBest ? ' style="background:#ff6b6b10;"' : '') + '>';
                        html += '<td style="font-weight:700;color:#e6edf3;">' + e.annee + (isBest ? ' &#11088;' : '') + '</td>';
                        if (e.temps_estime_brut) {
                            html += '<td style="color:#ff6b6b;font-weight:800;font-size:15px;">' + e.temps_estime_brut + '</td>';
                        } else {
                            html += '<td style="color:#8b949e;font-size:11px;">' + e.nb_disponibles + '/4 coureurs</td>';
                        }
                        for (var ci = 0; ci < 4; ci++) {
                            var c = e.coureurs[ci];
                            if (c) {
                                html += '<td><a href="?page=profil&id=' + c.id_externe + '" style="color:#58a6ff;text-decoration:none;font-size:12px;">' + _compE(c.nom) + '</a><br><span style="color:#f59e0b;font-size:11px;">' + c.perf_brut + '</span></td>';
                            } else {
                                html += '<td style="color:#5a6580;">-</td>';
                            }
                        }
                        html += '</tr>';
                    });
                    html += '</table>';
                    html += '<table class="bk-table">' + thRow + '</table>';
                    html += '</div>';
                    html += '</div>';
                });
            }

            // --- Epreuves individuelles ---
            if (sd.epreuves && sd.epreuves.length) {
                sd.epreuves.forEach(function(ep) {
                    ['M', 'F'].forEach(function(sx) {
                        if (sexeF && sexeF !== sx) return;
                        var athletes = ep[sx];
                        if (!athletes || !athletes.length) return;
                        html += '<h4 style="font-size:14px;font-weight:700;color:#c9d1d9;margin:16px 0 6px;">' + _compE(ep.nom) + ' <span style="display:inline-block;padding:1px 8px;border-radius:5px;font-size:10px;font-weight:700;' + (sx === 'M' ? 'background:#3b82f620;color:#60a5fa;border:1px solid #3b82f640;' : 'background:#ec489920;color:#f472b6;border:1px solid #ec489940;') + '">' + (sx === 'M' ? 'H' : 'F') + '</span></h4>';
                        var thRow = '<tr><th style="width:25px;">#</th><th>Athlete</th><th>Cat</th><th>NAT</th><th>Perf</th><th>Annee</th><th style="width:30px;"></th></tr>';
                        html += '<div class="table-wrap">';
                        html += '<table class="bk-table">' + thRow + '</table>';
                        html += '<table class="bk-table">';
                        athletes.forEach(function(a, i) {
                            var isExcl = !!sprintExcl[a.id_externe];
                            html += '<tr' + (isExcl ? ' style="opacity:0.3;text-decoration:line-through;"' : '') + '>';
                            html += '<td style="color:#8b949e;">' + (i + 1) + '</td>';
                            html += '<td><a href="?page=profil&id=' + a.id_externe + '" style="color:#58a6ff;text-decoration:none;font-weight:600;">' + _compE(a.nom) + '</a></td>';
                            html += '<td style="color:#8b949e;font-size:11px;">' + (a.categorie || '-') + '</td>';
                            html += '<td style="font-size:11px;">' + (a.nationalite || '-') + '</td>';
                            html += '<td style="color:#f59e0b;font-weight:700;">' + (a.perf_brut || _compP(a.perf_int)) + '</td>';
                            html += '<td style="color:#8b949e;font-size:11px;">' + (a.annee || '') + '</td>';
                            html += '<td><button onclick="_clubSprintExcl(' + a.id_externe + ',\'' + s + '\')" style="padding:1px 6px;border-radius:4px;border:1px solid ' + (isExcl ? '#3fb950' : '#f8717140') + ';background:transparent;color:' + (isExcl ? '#3fb950' : '#f87171') + ';font-size:10px;cursor:pointer;" title="' + (isExcl ? 'Reinclure' : 'Exclure') + '">' + (isExcl ? '&#10003;' : '&#10005;') + '</button></td>';
                            html += '</tr>';
                        });
                        html += '</table>';
                        html += '<table class="bk-table">' + thRow + '</table>';
                        html += '</div>';
                    });
                });
            }

            if (!sd.epreuves || !sd.epreuves.length) {
                html += '<div style="text-align:center;padding:20px;color:#8b949e;">Aucune donnee sprint trouvee pour ce club</div>';
            }

            // Bouton recharger
            html += '<div style="text-align:center;margin-top:16px;">';
            html += '<button onclick="_clubSprintLoad(\'' + s + '\')" style="padding:6px 16px;border-radius:8px;border:1px solid #30363d;background:transparent;color:#8b949e;font-size:12px;cursor:pointer;">Recharger</button>';
            html += '</div>';
        }
    } else if (tab === 'generations') {
        var yrs = d.annees_naissance_disponibles || [];
        var selN = (d.filter_annee_naissance ? String(d.filter_annee_naissance).split(',') : []).filter(Boolean);
        html += '<div style="margin-bottom:16px;padding:14px 18px;background:linear-gradient(135deg,#a78bfa18,#6c5ce718);border:1px solid #a78bfa55;border-radius:12px;">';
        html += '<div style="font-size:16px;font-weight:800;color:#c4b5fd;display:flex;align-items:center;gap:8px;">&#127874; Athletes par annee de naissance</div>';
        html += '<div style="color:#8b949e;font-size:12px;margin-top:4px;">Selectionnez une ou plusieurs annees pour filtrer tout le panneau (epreuves, records, stats, resume...).</div>';
        html += '</div>';
        if (!yrs.length) {
            html += '<div style="text-align:center;padding:30px;color:#8b949e;">Aucune annee de naissance renseignee pour ce club.</div>';
        } else {
            // Barre d'action : selection courante + reset
            html += '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px;">';
            if (selN.length) {
                html += '<span style="color:#c4b5fd;font-size:13px;font-weight:700;">' + selN.length + ' annee' + (selN.length > 1 ? 's' : '') + ' selectionnee' + (selN.length > 1 ? 's' : '') + '</span>';
                html += '<button onclick="_clubSetNaissance(\'\',\'' + s + '\')" style="padding:4px 12px;border-radius:8px;border:1px solid #f8717140;background:transparent;color:#f87171;font-size:12px;cursor:pointer;font-weight:600;">&#10005; Tout afficher</button>';
            } else {
                html += '<span style="color:#8b949e;font-size:13px;">Toutes les generations affichees &mdash; cliquez une annee pour filtrer</span>';
            }
            html += '</div>';
            // Distribution visuelle (barres horizontales cliquables)
            var maxN = 0;
            yrs.forEach(function(y) { if (y.nb > maxN) maxN = y.nb; });
            var nowY = new Date().getFullYear();
            html += '<div style="display:flex;flex-direction:column;gap:6px;">';
            yrs.forEach(function(y) {
                var isSel = selN.indexOf(String(y.annee)) !== -1;
                var pct = maxN > 0 ? Math.round(y.nb / maxN * 100) : 0;
                var age = nowY - y.annee;
                html += '<div onclick="_clubToggleNaissance(' + y.annee + ',\'' + s + '\')" style="display:flex;align-items:center;gap:10px;padding:7px 12px;border-radius:10px;cursor:pointer;border:1px solid ' + (isSel ? '#a78bfa' : '#1e2a3a') + ';background:' + (isSel ? '#a78bfa18' : 'transparent') + ';transition:all .15s;">';
                html += '<span style="min-width:46px;font-weight:800;font-size:14px;color:' + (isSel ? '#c4b5fd' : '#c9d1d9') + ';">' + y.annee + '</span>';
                html += '<span style="min-width:52px;font-size:10px;color:#5a6580;">~' + age + ' ans</span>';
                html += '<div style="flex:1;height:14px;background:#0d1117;border-radius:7px;overflow:hidden;"><div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,#6c5ce7,#a78bfa);border-radius:7px;"></div></div>';
                html += '<span style="min-width:58px;text-align:right;font-size:12px;font-weight:700;color:' + (isSel ? '#c4b5fd' : '#8b949e') + ';">' + y.nb.toLocaleString('fr-FR') + '</span>';
                html += '<span style="width:14px;text-align:center;color:#a78bfa;font-weight:700;">' + (isSel ? '&#10003;' : '') + '</span>';
                html += '</div>';
            });
            html += '</div>';
        }
    }
    content.innerHTML = html;
    // Post-render: graphique comparaison années pour onglet épreuves
    if (tab === 'epreuves') {
        // Graphique comparaison années
        var _cmpChartEl = document.getElementById('clubEpYearCmpChart' + s);
        var _cmpData = window['_clubEpYearCmpData' + s];
        if (_cmpChartEl && _cmpData) {
            var _cmpYrs = Object.keys(_cmpData).map(Number).sort();
            var _cmpColors = ['#6c5ce7','#00cec9','#fdcb6e','#e17055','#55efc4'];
            var _cmpDS = [
                { label:'Épreuves', key:'total_epreuves' },
                { label:'Athlètes', key:'total_athletes' },
                { label:'Records', key:'total_records' },
                { label:'Résultats', key:'nb_resultats' }
            ];
            new Chart(_cmpChartEl, {
                type: 'bar',
                data: {
                    labels: _cmpYrs.map(String),
                    datasets: _cmpDS.map(function(ds, di) {
                        return {
                            label: ds.label,
                            data: _cmpYrs.map(function(y) { return _cmpData[y][ds.key] || 0; }),
                            backgroundColor: _cmpColors[di]
                        };
                    })
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { position:'bottom', labels: { color:'#8b949e', padding:12, font:{size:11} } } },
                    scales: {
                        x: { grid:{color:'#1e2a3a'}, ticks:{color:'#8b949e'} },
                        y: { beginAtZero:true, grid:{color:'#1e2a3a'}, ticks:{color:'#5a6580'} }
                    }
                }
            });
        }
    }
    // Post-render: charts for nationalités tab
    if (tab === 'nationalites') {
        var _nat = d.nationalites || {};
        var _nk = Object.keys(_nat);
        var _totalN = 0;
        _nk.forEach(function(k) { _totalN += _nat[k]; });
        var _colors = ['#3b82f6','#ec4899','#8b5cf6','#f59e0b','#10b981','#ef4444','#06b6d4','#f97316','#84cc16','#6366f1','#64748b'];
        // Doughnut
        var _dc = document.getElementById('clubNatDonut' + s);
        if (_dc && _nk.length > 0) {
            var _top10 = _nk.slice(0, 10);
            var _otherC = 0;
            _nk.slice(10).forEach(function(k) { _otherC += _nat[k]; });
            var _lbl = _top10.map(function(k) { return k; });
            var _dt = _top10.map(function(k) { return _nat[k]; });
            if (_otherC > 0) { _lbl.push('Autres'); _dt.push(_otherC); }
            new Chart(_dc, {
                type: 'doughnut',
                data: { labels: _lbl, datasets: [{ data: _dt, backgroundColor: _colors.slice(0, _lbl.length), borderWidth: 0 }] },
                options: { responsive: true, cutout: '60%', plugins: { legend: { position: 'bottom', labels: { padding: 8, usePointStyle: true, font: { size: 10 }, color: '#8b949e' } } } }
            });
        }
        // Bar
        var _bc = document.getElementById('clubNatBar' + s);
        if (_bc && _nk.length > 0) {
            var _top15 = _nk.slice(0, 15);
            new Chart(_bc, {
                type: 'bar',
                data: { labels: _top15, datasets: [{ data: _top15.map(function(k) { return _nat[k]; }), backgroundColor: '#a78bfa', borderRadius: 4, barThickness: 16 }] },
                options: { indexAxis: 'y', responsive: true, plugins: { legend: { display: false } }, scales: { x: { grid: { color: '#1e2a3a' }, ticks: { color: '#8b949e' } }, y: { grid: { display: false }, ticks: { color: '#c8cfd8' } } } }
            });
        }
        // Comparison charts
        var _cmpD = window['_clubNatCmp' + s];
        var _cmpBar = document.getElementById('clubNatCmpBar' + s);
        if (_cmpBar && _cmpD) {
            var _natCl = ['#a78bfa','#f472b6','#34d399','#fbbf24','#60a5fa','#fb923c','#e879f9','#22d3ee'];
            new Chart(_cmpBar, {
                type: 'bar',
                data: { labels: _cmpD.map(function(n){return n.code;}), datasets: [{ label:'Athlètes', data: _cmpD.map(function(n){return n.nb_athletes;}), backgroundColor: _cmpD.map(function(_,i){return _natCl[i%_natCl.length];}), borderRadius:4, barThickness:28 }] },
                options: { responsive:true, plugins:{legend:{display:false}}, scales:{ x:{grid:{color:'#1e2a3a'},ticks:{color:'#c8cfd8',font:{weight:'bold'}}}, y:{grid:{color:'#1e2a3a'},ticks:{color:'#8b949e'},beginAtZero:true} } }
            });
        }
        var _cmpCat = document.getElementById('clubNatCmpCat' + s);
        if (_cmpCat && _cmpD) {
            var _natCl2 = ['#a78bfa','#f472b6','#34d399','#fbbf24','#60a5fa','#fb923c','#e879f9','#22d3ee'];
            var allCats = {};
            _cmpD.forEach(function(n) { Object.keys(n.par_categorie||{}).forEach(function(c) { allCats[c]=1; }); });
            var catKeys = Object.keys(allCats);
            new Chart(_cmpCat, {
                type: 'bar',
                data: { labels: catKeys, datasets: _cmpD.map(function(n,i) { return { label:n.code, data:catKeys.map(function(c){return (n.par_categorie||{})[c]||0;}), backgroundColor:_natCl2[i%_natCl2.length], borderRadius:3 }; }) },
                options: { responsive:true, plugins:{legend:{labels:{color:'#8b949e'}}}, scales:{ x:{grid:{color:'#1e2a3a'},ticks:{color:'#8b949e'}}, y:{grid:{color:'#1e2a3a'},ticks:{color:'#8b949e'},beginAtZero:true} } }
            });
        }
    }
    // Post-render: charts for stats tab
    if (tab === 'stats') {
        var _sexe = d.par_sexe || {};
        var _cats = d.par_categorie || {};
        var _rpa = (d.resultats_par_annee || []).slice().reverse();
        // Sexe doughnut
        var _sc = document.getElementById('clubSexeChart' + s);
        if (_sc) {
            var _sk = Object.keys(_sexe);
            new Chart(_sc, {
                type: 'doughnut',
                data: { labels: _sk.map(function(k){return k==='M'?'Hommes':(k==='F'?'Femmes':k);}), datasets: [{ data: _sk.map(function(k){return _sexe[k];}), backgroundColor: ['#3b82f6','#ec4899','#64748b'], borderWidth: 0 }] },
                options: { responsive: true, cutout: '60%', plugins: { legend: { position: 'bottom', labels: { padding: 8, usePointStyle: true, font: { size: 10 }, color: '#8b949e' } } } }
            });
        }
        // Categories bar
        var _cc = document.getElementById('clubCatChart' + s);
        if (_cc) {
            var _ck = Object.keys(_cats).slice(0, 12);
            new Chart(_cc, {
                type: 'bar',
                data: { labels: _ck, datasets: [{ data: _ck.map(function(k){return _cats[k];}), backgroundColor: '#34d399', borderRadius: 4, barThickness: 16 }] },
                options: { indexAxis: 'y', responsive: true, plugins: { legend: { display: false } }, scales: { x: { grid: { color: '#1e2a3a' }, ticks: { color: '#8b949e' } }, y: { grid: { display: false }, ticks: { color: '#c8cfd8' } } } }
            });
        }
        // Evolution line chart
        var _ec = document.getElementById('clubEvoChart' + s);
        if (_ec && _rpa.length > 1) {
            new Chart(_ec, {
                type: 'line',
                data: {
                    labels: _rpa.map(function(r){return r.annee;}),
                    datasets: [
                        { label: 'Résultats', data: _rpa.map(function(r){return r.nb_resultats;}), borderColor: '#6366f1', backgroundColor: '#6366f120', fill: true, tension: 0.3, pointRadius: 3 },
                        { label: 'Athlètes', data: _rpa.map(function(r){return r.nb_athletes;}), borderColor: '#34d399', backgroundColor: '#34d39920', fill: true, tension: 0.3, pointRadius: 3 }
                    ]
                },
                options: { responsive: true, plugins: { legend: { position: 'top', labels: { usePointStyle: true, font: { size: 10 }, color: '#8b949e' } } }, scales: { x: { grid: { color: '#1e2a3a' }, ticks: { color: '#8b949e' } }, y: { grid: { color: '#1e2a3a' }, ticks: { color: '#8b949e' } } }, interaction: { intersect: false, mode: 'index' } }
            });
        }
        // Distribution niveaux de compétition
        var _ep = d.epreuves || [];
        var _nivC = {}, _nivO = {IE:100,IR:99};
        ['N','R','D'].forEach(function(p){var b={N:90,R:80,D:70}[p];for(var i=1;i<=8;i++) _nivO[p+i]=b-i;});
        _ep.forEach(function(e) { (e.niveaux||[]).forEach(function(n){ if(n&&_nivO[n]) _nivC[n]=(_nivC[n]||0)+1; }); });
        var _nck = Object.keys(_nivC).sort(function(a,b){ return (_nivO[a]||0)-(_nivO[b]||0); });
        var _cvs = document.getElementById('clubNivChart' + s);
        if (_cvs && _nck.length > 2) {
            var _clrs = _nck.map(function(k){
                var c=k.charAt(0);
                return c==='I'?'#e879f9': c==='N'?'#fb7185': c==='R'?'#22d3ee': '#fb923c';
            });
            new Chart(_cvs, {
                type: 'line',
                data: {
                    labels: _nck,
                    datasets: [{
                        label: '\u00c9preuves',
                        data: _nck.map(function(k){ return _nivC[k]; }),
                        borderColor: '#a29bfe',
                        backgroundColor: '#a29bfe15',
                        tension: 0.4,
                        fill: true,
                        pointBackgroundColor: _clrs,
                        pointBorderColor: _clrs,
                        pointRadius: 5,
                        pointHoverRadius: 8,
                        borderWidth: 2.5
                    }]
                },
                options: {
                    responsive: true,
                    plugins: {
                        legend: { display: false },
                        tooltip: { callbacks: { label: function(ctx) { return ctx.parsed.y + ' \u00e9preuve' + (ctx.parsed.y > 1 ? 's' : ''); } } }
                    },
                    scales: {
                        x: { grid: { color: '#1e2a3a' }, ticks: { color: function(ctx) { var lbl=ctx.tick.label||'';var c=lbl.charAt(0);return c==='I'?'#e879f9':c==='N'?'#fb7185':c==='R'?'#22d3ee':'#fb923c'; }, font: { weight:'bold', size:11 } } },
                        y: { beginAtZero: true, grid: { color: '#1e2a3a' }, ticks: { color: '#5a6580', stepSize: 1 } }
                    }
                }
            });
        }
        // Évolution niveaux par année
        var _npa = d.niveaux_par_annee || [];
        var _ycvs = document.getElementById('clubNivYearChart' + s);
        if (_ycvs && _npa.length > 1) {
            var _yLabels = _npa.map(function(r){ return r.annee; });
            var _families = [
                { key:'D', label:'D\u00e9partemental', color:'#fb923c', bg:'#fb923c20' },
                { key:'R', label:'R\u00e9gional', color:'#22d3ee', bg:'#22d3ee20' },
                { key:'N', label:'National', color:'#fb7185', bg:'#fb718520' },
                { key:'I', label:'International', color:'#e879f9', bg:'#e879f920' }
            ];
            var _yds = [];
            _families.forEach(function(f) {
                var hasData = _npa.some(function(r){ return (r[f.key]||0) > 0; });
                if (hasData) {
                    _yds.push({ label:f.label, data:_npa.map(function(r){return r[f.key]||0;}), borderColor:f.color, backgroundColor:f.bg, tension:0.4, fill:false, pointRadius:4, pointHoverRadius:7, borderWidth:2.5 });
                }
            });
            new Chart(_ycvs, {
                type: 'line',
                data: { labels: _yLabels, datasets: _yds },
                options: {
                    responsive: true,
                    interaction: { mode: 'index', intersect: false },
                    plugins: { legend: { position:'bottom', labels: { padding:12, usePointStyle:true, pointStyleWidth:10, font:{size:11}, color:'#8b949e' } } },
                    scales: {
                        x: { grid:{color:'#1e2a3a'}, ticks:{color:'#8b949e', font:{size:11}} },
                        y: { beginAtZero:true, grid:{color:'#1e2a3a'}, ticks:{color:'#5a6580'} }
                    }
                }
            });
        }
    }
}
// --- Resume club : fonctions utilitaires ---
function _buildResumeText(d, annee) {
    var txt = [];
    var nom = d.club.nom_club;
    var nbAth = d.total_athletes || 0;
    var sexe = d.par_sexe || {};
    var cats = d.par_categorie || {};
    var nats = d.nationalites || {};
    var med = d.medailles || { or: 0, argent: 0, bronze: 0 };
    var medDetail = d.medailles_detail || [];
    var pod = d.podiums || {};
    var totalPod = d.total_podiums || 0;
    var podNiv = d.podium_niveaux || [];
    var sel = d.selections || {};
    var ep = d.epreuves || [];
    var rec = d.records || [];
    var totalRec = d.total_records || 0;
    var topAth = d.top_athletes || [];
    var topVilles = d.top_villes || [];
    var prog = d.progressions || {};
    var nivRes = d.niveaux_resultats || [];
    var nbResGlobal = d.nb_resultats_global || 0;
    var nbEpGlobal = d.nb_epreuves_global || 0;
    var anDebut = d.annee_debut;
    var anFin = d.annee_fin;
    var anDispo = d.annees_disponibles || [];
    var nivData = d.niveaux || [];
    var bestNiv = d.meilleur_niveau;
