<div class="report-overlay" id="reportOverlay">
    <div class="report-modal">
        <button class="btn-close" onclick="closeReportModal()" style="position:absolute;top:12px;right:12px;background:none;border:none;color:#8b949e;font-size:24px;cursor:pointer;">&times;</button>
        <h3>&#9888; Signaler ce profil</h3>
        <p id="reportAthleteName" style="color:#c9d1d9;font-weight:600;margin-bottom:4px;"></p>
        <p style="color:#ef4444;font-size:13px;font-weight:600;margin:0 0 16px;line-height:1.5;">&#9993; Votre adresse email est <u>obligatoire</u> pour valider votre signalement. Pour un retrait, nous vous enverrons un lien de confirmation pour retirer votre profil instantanement. Sans email valide, votre demande ne sera pas enregistree.</p>
        <input type="hidden" id="reportAthleteId" value="">
        <input type="hidden" id="reportAthleteNameVal" value="">
        <label for="reportReason">Motif du signalement</label>
        <select id="reportReason" onchange="(function(v){var h=document.getElementById('reportRetraitHint');if(v==='retrait'){h.style.display='block';}else{h.style.display='none';}})(this.value)">
            <option value="">-- Choisir un motif --</option>
            <option value="retrait">Je souhaite retirer mon profil</option>
            <option value="donnees_incorrectes">Donnees incorrectes</option>
            <option value="usurpation">Usurpation d'identite</option>
            <option value="vie_privee">Atteinte a la vie privee</option>
            <option value="autre">Autre</option>
        </select>
        <div id="reportRetraitHint" style="display:none;background:#ef444415;border:1px solid #ef444440;border-radius:8px;padding:10px 14px;margin:8px 0 12px;">
            <p style="color:#ef4444;font-size:13px;font-weight:600;margin:0;line-height:1.5;">&#9888; L'email est obligatoire pour ce motif. Vous recevrez un lien de confirmation : un seul clic et votre profil sera <strong>retire des resultats de recherche et de Google</strong>. Vos donnees sont conservees, restauration possible sur demande.</p>
        </div>
        <label for="reportMessage">Details (facultatif)</label>
        <textarea id="reportMessage" placeholder="Precisez votre demande..." maxlength="2000"></textarea>
        <label for="reportEmail" id="reportEmailLabel">Email de contact <span style="color:#ef4444">*</span></label>
        <input type="email" id="reportEmail" placeholder="votre@email.com" required>
        <button class="btn-submit-report" id="btnSubmitReport" onclick="submitReport()">Envoyer le signalement</button>
        <div id="reportFeedback"></div>
    </div>
</div>
<script>
// === Admin : Masquer un profil (soft delete, reversible) ===
window.adminSoftHideProfile = function(athleteId, athleteName) {
    var msg = "MASQUER LE PROFIL (action reversible)\n\n"
            + athleteName + " (ID " + athleteId + ")\n\n"
            + "Effets :\n"
            + "  • Disparait des resultats Google (410 Gone)\n"
            + "  • Disparait de la recherche, listes, stats, sitemap\n"
            + "  • Plus accessible via son URL directe\n\n"
            + "Donnees conservees en BDD. Restauration possible en 1 clic.\n\n"
            + "Continuer ?";
    if (!confirm(msg)) return;
    fetch('api/report.php?soft_hide=' + encodeURIComponent(athleteId), { credentials: 'same-origin' })
        .then(function(r) { return r.json().then(function(j) { return { status: r.status, json: j }; }); })
        .then(function(res) {
            if (res.json && res.json.success) {
                alert('Profil ' + athleteName + ' masque.\n'
                    + (res.json.affected || 0) + ' ligne(s) BDD mises a jour\n'
                    + (res.json.cache_cleared || 0) + ' fichier(s) cache vides\n\n'
                    + 'Pour restaurer : reviens sur ce profil et clique "Restaurer".');
                window.location.reload();
            } else {
                alert('Erreur : ' + (res.json && res.json.error ? res.json.error : 'HTTP ' + res.status));
            }
        })
        .catch(function(err) { alert('Erreur reseau : ' + err.message); });
};

// === Admin : Restaurer un profil masque ===
window.adminRestoreProfile = function(athleteId, athleteName) {
    if (!confirm('Restaurer le profil ' + athleteName + ' (le rendre a nouveau visible) ?')) return;
    fetch('api/report.php?restore=' + encodeURIComponent(athleteId), { credentials: 'same-origin' })
        .then(function(r) { return r.json().then(function(j) { return { status: r.status, json: j }; }); })
        .then(function(res) {
            if (res.json && res.json.success) {
                alert('Profil ' + athleteName + ' restaure.\nRechargement...');
                window.location.reload();
            } else {
                alert('Erreur : ' + (res.json && res.json.error ? res.json.error : 'HTTP ' + res.status));
            }
        })
        .catch(function(err) { alert('Erreur reseau : ' + err.message); });
};

// === Admin : suppression definitive d'un profil depuis la page profil ===
window.adminPurgeProfile = function(athleteId, athleteName) {
    var msg = "⚠ SUPPRESSION DEFINITIVE\n\n"
            + "Vous allez supprimer DEFINITIVEMENT :\n"
            + "  " + athleteName + " (ID " + athleteId + ")\n\n"
            + "Cette action va :\n"
            + "  • Effacer toutes les donnees (records, progressions, resultats, medailles, podiums)\n"
            + "  • Supprimer le compte utilisateur lie si existe\n"
            + "  • Blacklister l'athlete (empeche tout re-scraping futur)\n"
            + "  • Retirer de Google (HTTP 410 Gone)\n\n"
            + "IRREVERSIBLE. Continuer ?";
    if (!confirm(msg)) return;
    var confirm2 = prompt('Pour confirmer, tapez SUPPRIMER (en majuscules) :');
    if (confirm2 !== 'SUPPRIMER') {
        alert('Suppression annulee.');
        return;
    }
    var btn = document.getElementById('btnAdminPurge') || event.target;
    if (btn) { btn.disabled = true; btn.textContent = 'Suppression en cours...'; }
    fetch('api/report.php?hide_athlete=' + encodeURIComponent(athleteId), { credentials: 'same-origin' })
        .then(function(r) { return r.json().then(function(j) { return { status: r.status, json: j }; }); })
        .then(function(res) {
            if (res.json && res.json.success) {
                var d = res.json.detail || {};
                var summary = 'Profil ' + athleteName + ' supprime.\n\n';
                if (d.deleted) {
                    if (d.deleted.athletes) summary += '• ' + d.deleted.athletes + ' ligne(s) athletes\n';
                    if (d.deleted.users) summary += '• ' + d.deleted.users + ' compte(s) user lie(s)\n';
                    if (d.deleted.nom_et_liens) summary += '• ' + d.deleted.nom_et_liens + ' entree(s) nom_et_liens\n';
                    if (d.deleted.search_tracking) summary += '• ' + d.deleted.search_tracking + ' entree(s) tracking\n';
                    if (d.deleted.cache_files) summary += '• ' + d.deleted.cache_files + ' fichier(s) cache\n';
                }
                summary += '\nRedirection vers l\'accueil...';
                alert(summary);
                window.location.href = '?page=accueil';
            } else {
                alert('Erreur : ' + (res.json && res.json.error ? res.json.error : 'reponse invalide (HTTP ' + res.status + ')'));
                if (btn) { btn.disabled = false; btn.innerHTML = '&#128465; Supprimer (admin)'; }
            }
        })
        .catch(function(err) {
            alert('Erreur reseau : ' + err.message);
            if (btn) { btn.disabled = false; btn.innerHTML = '&#128465; Supprimer (admin)'; }
        });
};

window.openReportModal = function(athleteId, athleteName) {
    document.getElementById('reportAthleteId').value = athleteId;
    document.getElementById('reportAthleteNameVal').value = athleteName;
    document.getElementById('reportAthleteName').textContent = athleteName;
    document.getElementById('reportReason').value = '';
    document.getElementById('reportMessage').value = '';
    document.getElementById('reportEmail').value = '';
    document.getElementById('reportFeedback').innerHTML = '';
    document.getElementById('btnSubmitReport').disabled = false;
    document.getElementById('btnSubmitReport').textContent = 'Envoyer le signalement';
    document.getElementById('reportOverlay').classList.add('active');
};
window.closeReportModal = function() {
    document.getElementById('reportOverlay').classList.remove('active');
};
document.getElementById('reportOverlay').addEventListener('click', function(e) {
    if (e.target === this) closeReportModal();
});
document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && document.getElementById('reportOverlay').classList.contains('active')) closeReportModal();
});
window.submitReport = function() {
    var reason = document.getElementById('reportReason').value;
    var message = document.getElementById('reportMessage').value.trim();
    var email = document.getElementById('reportEmail').value.trim();
    var athleteId = parseInt(document.getElementById('reportAthleteId').value);
    var athleteName = document.getElementById('reportAthleteNameVal').value;
    var fb = document.getElementById('reportFeedback');
    var btn = document.getElementById('btnSubmitReport');
    if (!reason) { fb.innerHTML = '<div class="report-error">Veuillez choisir un motif.</div>'; return; }
    if (!email) { fb.innerHTML = '<div class="report-error">&#9993; Adresse email obligatoire pour valider votre signalement.</div>'; return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { fb.innerHTML = '<div class="report-error">&#9888; Adresse email invalide. Veuillez verifier votre saisie.</div>'; return; }
    btn.disabled = true;
    btn.textContent = 'Envoi en cours...';
    fetch(BASE_API + '/report.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ athlete_id: athleteId, athlete_name: athleteName, reason: reason, message: message, email: email })
    })
    .then(function(r) { return r.json().then(function(d) { return { ok: r.ok, data: d }; }); })
    .then(function(res) {
        if (res.ok && res.data.success) {
            if (res.data.confirm_sent) {
                fb.innerHTML = '<div style="background:#a29bfe15;border:2px solid #a29bfe;border-radius:12px;padding:18px 20px;margin-top:14px;text-align:center;line-height:1.7;">'
                    + '<div style="font-size:36px;margin-bottom:8px;">&#9993;</div>'
                    + '<strong style="color:#a29bfe;font-size:16px;">Verifiez votre boite mail !</strong><br>'
                    + '<span style="color:#c9d1d9;font-size:14px;">Un email a ete envoye a <strong>' + email + '</strong></span><br><br>'
                    + '<span style="color:#f0f6fc;font-size:15px;font-weight:700;">&#x1F449; Ouvrez l\'email et cliquez sur le bouton de confirmation pour masquer votre profil.</span><br><br>'
                    + '<span style="color:#8b949e;font-size:12px;">Sans confirmation, votre profil restera visible.<br>Pensez a verifier vos spams. Le lien expire dans 48h.</span>'
                    + '</div>';
            } else {
                fb.innerHTML = '<div class="report-success">&#10003; ' + (res.data.message || 'Signalement envoye.') + '</div>';
            }
            btn.textContent = 'Envoye';
        } else {
            fb.innerHTML = '<div class="report-error">' + (res.data.error || 'Erreur inconnue') + '</div>';
            btn.disabled = false;
            btn.textContent = 'Envoyer le signalement';
        }
    })
    .catch(function() {
        fb.innerHTML = '<div class="report-error">Erreur reseau, reessayez.</div>';
        btn.disabled = false;
        btn.textContent = 'Envoyer le signalement';
    });
};
</script>

<!-- Modal Connexion requise (Follow + PDF) -->
<div class="follow-overlay" id="loginRequiredOverlay">
    <div class="follow-modal" style="position:relative;text-align:center;">
        <button class="btn-close" onclick="closeLoginRequired()">&times;</button>
        <div style="font-size:40px;margin-bottom:12px;" id="loginReqIcon">&#9825;</div>
        <h3 id="loginReqTitle">Connexion requise</h3>
        <p id="loginReqDesc" style="color:#8b949e;margin-bottom:20px;">Connectez-vous avec Google pour utiliser cette fonctionnalite.</p>
        <a href="login.php" class="btn-google-modal" style="display:inline-flex;align-items:center;justify-content:center;gap:10px;width:100%;padding:14px;background:#fff;color:#3c4043;border:1px solid #dadce0;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;text-decoration:none;transition:background .2s,box-shadow .2s;">
            <svg width="20" height="20" viewBox="0 0 48 48"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59a14.5 14.5 0 0 1 0-9.18l-7.98-6.19a24.08 24.08 0 0 0 0 21.56l7.98-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>
            Se connecter avec Google
        </a>
        <p style="font-size:11px;color:#484f58;margin-top:16px;margin-bottom:0;">Gratuit et rapide. Aucun spam.</p>
    </div>
</div>

<script>
(function() {
    var _followAthleteId = null;
    var _bkUser = null;
    window._bkUser = null;

    // Verifier si l'utilisateur est connecte
    fetch(BASE_API + '/auth/me.php', { credentials: 'same-origin' })
        .then(function(r) { return r.json(); })
        .then(function(data) { if (data.authenticated) { _bkUser = data.user; window._bkUser = data.user; } })
        .catch(function() {});

    window._showLoginRequired = function(icon, title, desc) {
        document.getElementById('loginReqIcon').innerHTML = icon || '\u2661';
        document.getElementById('loginReqTitle').textContent = title || 'Connexion requise';
        document.getElementById('loginReqDesc').textContent = desc || 'Connectez-vous avec Google pour utiliser cette fonctionnalite.';
        document.getElementById('loginRequiredOverlay').classList.add('active');
    };
    window.closeLoginRequired = function() {
        document.getElementById('loginRequiredOverlay').classList.remove('active');
    };
    document.getElementById('loginRequiredOverlay').addEventListener('click', function(e) {
        if (e.target === this) closeLoginRequired();
    });
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeLoginRequired();
    });

    window.toggleFollow = function(athleteId) {
        _followAthleteId = athleteId;
        if (!_bkUser) {
            _showLoginRequired('\u2661', 'Suivre cet athlete', 'Connectez-vous avec Google pour suivre cet athlete et etre notifie de ses nouveaux resultats.');
            return;
        }
        _doFollow(athleteId, _bkUser.email);
    };

    function _doFollow(athleteId, email) {
        var btn = document.getElementById('btnFollow');
        if (btn) btn.textContent = '...';
        fetch(BASE_API + '/follow.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'same-origin',
            body: JSON.stringify({ athlete_id: athleteId, email: email })
        })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            if (!data.success) { if (btn) btn.textContent = '\u2661 Suivre'; return; }
            _updateFollowBtn(data.following, data.count);
        })
        .catch(function() { if (btn) btn.textContent = '\u2661 Suivre'; });
    }

    function _updateFollowBtn(following, count) {
        var btn = document.getElementById('btnFollow');
        if (!btn) return;
        if (following) {
            btn.className = 'btn-follow following';
            btn.innerHTML = '\u2665 Suivi' + (count > 0 ? ' <span class="follow-count">' + count + '</span>' : '');
        } else {
            btn.className = 'btn-follow';
            btn.innerHTML = '\u2661 Suivre' + (count > 0 ? ' <span class="follow-count">' + count + '</span>' : '');
        }
    }

    // Init : verifier etat au chargement du profil
    function _checkFollowStatus() {
        var btn = document.getElementById('btnFollow');
        if (!btn || !_bkUser) return;
        var athleteId = btn.getAttribute('onclick');
        if (!athleteId) return;
        var m = athleteId.match(/toggleFollow\((\d+)\)/);
        if (!m) return;
        var id = m[1];
        var url = BASE_API + '/follow.php?athlete_id=' + id + '&email=' + encodeURIComponent(_bkUser.email);
        fetch(url, { credentials: 'same-origin' })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            if (data.success) _updateFollowBtn(data.following, data.count);
        })
        .catch(function() {});
    }
    // Attendre que _bkUser soit charge
    setTimeout(_checkFollowStatus, 500);
})();
</script>

<!-- Club Follow JS -->
<script>
(function() {
    var _clubFollowPending = null;

    window.toggleFollowClub = function(clubId, suffix) {
        _clubFollowPending = { clubId: clubId, suffix: suffix || '' };
